353. export function resolveModelProvidersPath(filePath?: string): string | null {
354.     const envOverridePath = process.env.PS_MODEL_PROVIDERS_PATH || process.env.MODEL_PROVIDERS_PATH;
355.     const overridePath = filePath || envOverridePath;
356.     if (overridePath && fs.existsSync(overridePath)) return overridePath;
357. 
358.     const searchPaths = [
359.         ".model_providers.json",
360.         path.join(process.cwd(), ".model_providers.json"),
361.         "/app/.model_providers.json",
362.         // Legacy fallback
